import sys

def read_text_safely(filename):
    try:
        with open(filename, "r", encoding="utf-8") as f:
            return f.read()
    except FileNotFoundError:
        return sys.stdin.read()

# 文件 missing.txt 不存在，自动无缝回退到 stdin！
raw = read_text_safely("missing.txt")
pairs = []
for line in raw.splitlines():
    parts = line.split()
    if len(parts) >= 2:
        pairs.append((parts[0], int(parts[1])))

scores = [sc for _, sc in pairs]
print(f"人数: {len(pairs)}, 最高分: {max(scores)}, 平均分: {sum(scores)/len(scores):.2f}")

