raw = "China’s cup, China’s pride! The cup is a “great” cup."

# 故意演示：如果标点串漏了弯引号 ’ ‘ “ ”，结果会出错
bad_punct = ",.!\""
bad_text = raw
for ch in bad_punct:
    bad_text = bad_text.replace(ch, " ")
print("漏弯引号切词(错):", bad_text.lower().split())

# 正确做法：标点串必须包含 Unicode 弯引号 ’ ‘ “ ”
good_punct = "#$%&()'’‘“”!\"\\*+,-./:;<=>?@[]^_{|}~"
text = raw
for ch in good_punct:
    text = text.replace(ch, " ")
excluded = {"the", "is", "a", "s"}
cnt = {}
for w in text.lower().split():
    if w not in excluded:
        cnt[w] = cnt.get(w, 0) + 1
ranked = sorted(cnt.items(), key=lambda kv: -kv[1])
print("正确去弯引号词频:", ranked)

