sample_cup = """China’s Cup is held in Beijing. The Cup has a long history,
and China’s students love Python and “Cup” competitions!
Python makes Cup data analysis fast and clean."""

with open("cup.txt", "w", encoding="utf-8") as f:
    f.write(sample_cup)

with open("cup.txt", "r", encoding="utf-8") as f:
    text = f.read()

biaodian = "#$%&()'’‘“”!\"\\*+,-./:;<=>?@[]^_{|}~"
for ch in biaodian:
    text = text.replace(ch, " ")

excluded = {"the", "and", "of", "in", "with", "a", "has", "to", "it", "for", "at", "is", "on", "from", "s"}
cnt = {}
for w in text.lower().split():
    if w not in excluded:
        cnt[w] = cnt.get(w, 0) + 1

ranked = sorted(cnt.items(), key=lambda kv: -kv[1])
for w, c in ranked[:5]:
    print(w, c)
